"""JSON value operations kept separate from filter evaluation."""

from __future__ import annotations

import json
import sys
import math
from typing import Any

JsonValue = None | bool | int | float | str | list["JsonValue"] | dict[str, "JsonValue"]


def parse_json_text(text: str) -> JsonValue:
    """Parse one JSON text using the standard-library JSON decoder."""
    return json.loads(text)


def serialize_compact(value: JsonValue) -> str:
    """Serialize a JSON value in jq's compact line-oriented form."""
    def normalize(item):
        if isinstance(item, float) and math.isfinite(item) and item.is_integer(): return int(item)
        if isinstance(item, list): return [normalize(child) for child in item]
        if isinstance(item, dict): return {key: normalize(child) for key, child in item.items()}
        return item
    value = normalize(value)
    old_limit = sys.getrecursionlimit()
    if old_limit < 1000000:
        sys.setrecursionlimit(1000000)
    try:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
    finally:
        if old_limit < 1000000:
            sys.setrecursionlimit(old_limit)


def is_truthy(value: Any) -> bool:
    """jq treats only false and null as falsey."""
    return value is not False and value is not None
"""Process boundary for the compact jq executable contract."""

from __future__ import annotations

import argparse
import sys
sys.setrecursionlimit(1000000)

from .data_model import parse_json_text, serialize_compact
from .diagnostics import CompileError
from .evaluator import evaluate
from .parser import parse


def _report(error: BaseException, fallback: str) -> None:
    """Write a useful diagnostic without ever contaminating stdout."""
    message = str(error).strip() or fallback
    print(message, file=sys.stderr)


def _arguments(argv: list[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(prog="jq")
    parser.add_argument("-c", dest="program", required=True)
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    try:
        arguments = _arguments(sys.argv[1:] if argv is None else argv)
        filter_ast = parse(arguments.program)
    except CompileError as exc:
        _report(exc, "filter compilation failed")
        return 3

    try:
        for line in sys.stdin:
            if not line.strip():
                continue
            input_value = parse_json_text(line)
            for output in evaluate(filter_ast, input_value):
                print(serialize_compact(output), flush=True)
    except Exception as exc:
        _report(exc, "runtime evaluation failed")
        return 5
    return 0

