    if depth > 10000: raise RuntimeJqError("Containment check too deep")
    if isinstance(a,str) and isinstance(b,str): return b in a
    if isinstance(a,list) and isinstance(b,list): return all(any(_contains(candidate, wanted, depth + 1) for candidate in a) for wanted in b)
